import React, { Component } from 'react'
import PropTypes from 'prop-types'
import {
  ContainerLayout,
  ContainerBody
} from './index.style'
import { Row, Col, Form, Button, Alert } from 'antd'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import CircularLoader from '../../../../../components/CircularLoader'
import { ERROR_STRINGS } from '../../../../../constants/lang'
import policyAction from '../../../../../redux/lazadaCrackScreenEndorse/actions'
import { getFormItems, errorHandler } from '../../../../../components/utility/formItems'
import { LAZADA_GADGET_PROTECTION } from '../../../constants'
import _ from 'lodash'
import IntlMessages from '../../../../../components/utility/intlMessages'
import EndorseWelcome from '../../../LazadaCrackScreenEndorsement/components/LazadaCrackScreenEndorsementThankYou'
const { getLazadaFullGadgetProtectionPolicyDetails, resetLazadaEndorseData, postLazadaCrackScreenEndorse } = policyAction

class LazadaCrackScreenEndorsement extends Component {
  constructor (props) {
    super(props)
    this.state = {
      insuredFieldDisabled: false,
      buttonDisabled: true
    }
  }
  static propTypes = {
    id: PropTypes.string
  }
  componentWillReceiveProps (nextProps) {
    const { submitSendoError, gosureDetailsMessage } = nextProps
    errorHandler.call(this, {
      submitError: submitSendoError,
      detailMessage: gosureDetailsMessage,
      resetFunction: () => this.props.resetLazadaEndorseData(['postLazadaCrackScreenEndorseMessage'])
    })
  }
  componentDidMount () {
    const { id } = this.props
    this.props.getLazadaFullGadgetProtectionPolicyDetails({ query: { id } })
  }
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }
  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }
  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }
  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    const body = {
      ...formBody,
      dob: formBody.dob.format('YYYY-MM-DD'),
      built_year: formBody.built_year.toString(),
      phone_no: `62${formBody.phone_no}`
    }

    this.props.postLazadaCrackScreenEndorse({ body, params: { id: this.props.id } })
  }
  render () {
    const {
      policyDetailLoading, detailsData, submitSendoLoading,
      policyDetailError, gosureDetailsMessage
    } = this.props
    const isSuccessFulEndorse = (gosureDetailsMessage === 'success') ||
    (_.get(detailsData, 'detail.EndorsementStatus', '') === 'SUCCESS')
    return (
      <ContainerLayout>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={policyDetailLoading || submitSendoLoading}>
              <ContainerBody>
                <h3 className='form-heading'><IntlMessages id='Aktivasi Asuransi Full Gadget Protection' /></h3>
                <p className='form-subheading'><IntlMessages id='Aktifkan Asuransi Full Gadget Protection Anda dengan mengisi rincian gadget secara benar.
      Jika rincian gadget Anda tidak benar, maka manfaat dari polis tidak dapat diklaim.' /></p>
                <Form onSubmit={this.handleFormSubmit}>
                  <Row>
                    {
                      LAZADA_GADGET_PROTECTION.map(val =>
                        <Col>
                          {getFormItems.call(this, val)}
                        </Col>
                      )
                    }
                  </Row>
                  <Row type='flex' justify='center' className='submit-button'>
                    <Col className='bottom-form'>
                      <Button
                        type='primary'
                        className='form-btn'
                        htmlType='submit'
                        key='submit'
                      >
                        <IntlMessages id='Kirim' />
                      </Button>
                    </Col>
                  </Row>
                </Form>
              </ContainerBody>
            </CircularLoader>
        }
      </ContainerLayout>
    )
  }
}
const LazadaCrackScreenEndorsementWrapped = Form.create()(LazadaCrackScreenEndorsement)
export default connect(
  state => ({
    detailsData: state.LazadaCrackScreen.lazadaFullGadgetProtectionDetails,
    policyDetailLoading: state.Loading.GET_LAZADA_FULL_GADGET_PROTECTION_POLICY_DETAIL,
    policyDetailError: state.Error.GET_LAZADA_FULL_GADGET_PROTECTION_POLICY_DETAIL,
    gosureDetailsMessage: state.LazadaCrackScreen.postLazadaCrackScreenEndorseMessage,
    submitSendoLoading: state.Loading.POST_LAZADA_POLICY_DETAIL,
    submitSendoError: state.Error.POST_LAZADA_POLICY_DETAIL
  }), {
    getLazadaFullGadgetProtectionPolicyDetails, resetLazadaEndorseData, postLazadaCrackScreenEndorse
  }
)(injectIntl(LazadaCrackScreenEndorsementWrapped))
